    public static int qmi(int base, int k) {
        long a = base; long res = 1;
        while (k > 0) {
            if ((k & 1) == 1) res = res * a % MOD;
            a =  a * a %  MOD;
            k >>= 1;
        }
        return (int)res;
    }

